C;oBAC1C,aAAa,EAAE,IAAI,CAAC,OAAO,CAAC,OAAO,CAAC,eAAe,CAAC;oBACpD,eAAe,EAAE,IAAI,CAAC,OAAO,CAAC,OAAO,CAAC,iBAAiB,CAAC;oBACxD,YAAY,EAAE,IAAI,CAAC,UAAU,CAAC,cAAc,CAAC;oBAC7C,aAAa,EAAE,IAAI,CAAC,UAAU,CAAC,eAAe,CAAC;oBAC/C,YAAY,EAAE,IAAI,CAAC,UAAU,CAAC,cAAc,CAAC;iBAChD,CAAC;gBACF,OAAO,EAAE,EAAE,QAAQ,EAAE,KAAK,EAAE,GAAG,EAAE,IAAI,EAAE,KAAK,EAAE,KAAK,EAAE,UAAU,EAAE,KAAK,EAAE;gBACxE,MAAM,EAAE,IAAI;aACf;YACD;gBACI,YAAY,EAAE,iBAAiB;gBAC/B,QAAQ,EAAE,GAAG,EAAE,CAAC,IAAI,CAAC,cAAc,CAAC;oBAChC,iBAAiB,EAAE,IAAI,CAAC,OAAO,CAAC,OAAO,CAAC,mBAAmB,CAAC;oBAC5D,mBAAmB,EAAE,IAAI,CAAC,OAAO,CAAC,OAAO,CAAC,qBAAqB,CAAC;oBAChE,cAAc,EAAE,IAAI,CAAC,OAAO,CAAC,OAAO,CAAC,gBAAgB,CAAC;oBACtD,cAAc,EAAE,IAAI,CAAC,UAAU,CAAC,gBAAgB,CAAC;iBACpD,CAAC;gBACF,OAAO,EAAE,EAAE,QAAQ,EAAE,KAAK,EAAE,GAAG,EAAE,IAAI,EAAE,KAAK,EAAE,KAAK,EAAE,UAAU,EAAE,KAAK,EAAE;gBACxE,MAAM,EAAE,IAAI;aACf;SACJ,CAAC;QAEN,KAAK,MAAM,GAAG,IAAI,SAAS,EAAE,CAAC;YAC1B,IAAI,CAAC;gBACD,MAAM,UAAU,GAAG,IAAI,CAAC,IAAI,CAAC,SAAS,EAAE,IAAI,EAAE,IAAI,EAAE,MAAM,EAAE,SAAS,EAAE,GAAG,CAAC,YAAY,CAAC,CAAC;gBACzF,MAAM,MAAM,GAAG,OAAO,CAAC,UAAU,CAAC,CAAC,OAAO,CAAC;gBAC3C,IAAI,CAAC,YAAY,CACb,MAAM,CAAC,SAAS,EAChB,MAAM,CAAC,YAAY,EACnB,MAAM,CAAC,iBAAiB,EACxB,MAAM,CAAC,YAAY,EACnB,GAAG,CAAC,QAAQ,EAAE,EACd,GAAG,CAAC,OAAO,EACX,GAAG,CAAC,MAAM,CACb,CAAC;YACN,CAAC;YAAC,OAAO,CAAM,EAAE,CAAC;gBACd,OAAO,CAAC,KAAK,CAAC,8CAA8C,GAAG,CAAC,YAAY,IAAI,EAAE,CAAC,CAAC,OAAO,CAAC,CAAC;YACjG,CAAC;QACL,CAAC;IACL,CAAC;IAEM,KAAK;QACR,0BAA0B;IAC9B,CAAC;CACJ;AA3UD,wCA2UC","sourcesContent":["import { BrowserWindow, ipcMain } from 'electron';\nimport * as fs from 'fs';\nimport * as path from 'path';\n\nimport { BaseWindow } from \"./BaseWindow\";\nimport { WindowManager } from \"./WindowManager\";\nimport { utils, sysConfig } from '../../utils/globals';\nimport { LLMService } from '../../core/LLMService';\nimport { ToolCall } from '../../core/ToolCall';\nimport { Plugins } from '../../core/Plugins';\nimport { Mode } from '../../core/ReActAgent';\n\ninterface AgentTool {\n    tool_call: ToolCall;\n    func: (params: { query: string }) => Promise<any>;\n    getPrompt: () => any;\n    mainSubAgent: boolean;\n    extra?: any;\n}\n\ninterface SubAgentOptions {\n    todolist?: boolean;\n    env?: boolean;\n    skill?: boolean;\n    mcp_server?: boolean;\n}\n\nexport class SubAgentWindow extends BaseWindow {\n    public agentToolName?: string;\n    public agentTool?: AgentTool;\n    public agentTools: Record<string, AgentTool>;\n    public windows: BrowserWindow[]; // 支持多个子 Agent 窗口\n    private windowListeners: Map<BrowserWindow, { minimize: () => void; close: () => void }>;\n    private plugins: Plugins;\n\n    constructor(windowManager: WindowManager) {\n        super(windowManager);\n        this.agentTools = {};\n        this.windows = [] as any; // 覆盖基类的 BrowserWindow | null\n        this.windowListeners = new Map();\n        this.plugins = new Plugins();\n        this.toolInit();\n    }\n\n    // 将工具统一为当前插件格式：{ func, getPrompt, extra? }\n    private normalizeTool(tool: any): any {\n        if (!tool) return null;\n        if (typeof tool.func === 'function' && typeof tool.getPrompt === 'function') {\n            return tool;\n        }\n        return null;\n    }\n\n    // 过滤无效工具，避免 undefined 传入 ToolCall\n    private normalizeTools(tools: Record<string, any>): Record<string, any> {\n        const normalized: Record<string, any> = {};\n        Object.entries(tools).forEach(([name, tool]) => {\n            const item = this.normalizeTool(tool);\n            if (item) normalized[name] = item;\n        });\n        return normalized;\n    }\n\n    public async query(query: string, agentToolName: string): Promise<any> {\n        return await this.create({ query, agentToolName });\n    }\n\n    public async create(params?: { query: string; agentToolName: string }): Promise<any> {\n        if (!params) return;\n        const { query, agentToolName } = params;\n\n        const win = new BrowserWindow({\n            width: 800 - Math.min(this.windows.length, 5) * 50,\n            height: 800 - Math.min(this.windows.length, 5) * 50,\n            frame: false,\n            transparent: false,\n            resizable: true,\n            webPreferences: {\n                preload: path.join(__dirname, '../preloads/subagent_window_preload.js'),\n            },\n        });\n\n        // win.webContents.openDevTools()\n\n        this.windows.push(win);\n\n        const listeners = {\n            minimize: () => win.minimize(),\n            close: () => {\n                if (win && !win.isDestroyed()) {\n                    win.close();\n                    this.windows = this.windows.filter(w => w !== win);\n                }\n            }\n        };\n\n        const result = await new Promise<any>((resolve) => {\n            this.windowListeners.set(win, listeners);\n\n            ipcMain.once(`minimize-window-${win.id}`, listeners.minimize);\n            ipcMain.once(`close-window-${win.id}`, listeners.close);\n\n            win.loadFile('src/frontend/subagent.html');\n\n            this.agentToolName = agentToolName;\n            this.agentTool = this.agentTools[agentToolName];\n\n            win.on('closed', () => {\n                if (this.agentTool) {\n                    this.agentTool.tool_call.changeWindow();\n                    this.agentTool.tool_call.llm_service.stopLoop();\n                    resolve(\"The user interrupted the task.\");\n                }\n            });\n\n            win.webContents.on('did-finish-load', async () => {\n                win.restore();\n                win.show();\n                win.focus();\n                win.webContents.send('windowInfo', { id: win.id, name: agentToolName });\n                if (this.agentTool) {\n                    this.agentTool.tool_call.changeWindow(win);\n                    // 子代理模式同主代理模式一样（计划模式例外）\n                    if (this.windowManager.mainWindow.tool_call.environment_details.mode !== Mode.PLAN) {\n                        this.agentTool.tool_call.changeMode(this.windowManager.mainWindow.llm_service.chatManager.chat.mode);\n                    } else {\n                        // 计划模式下，子代理默认为自动模式\n                        this.agentTool.tool_call.changeMode(\"auto\");\n                    }\n\n                    if (utils.getConfig(\"tool_call\")?.subagent_llm_init || this.windows.length > 1) {\n                        this.agentTool.tool_call.llm_service.chatManager.init();\n                    }\n                    const mainChat = this.windowManager.mainWindow.llm_service.chatManager.chat;\n                    this.agentTool.tool_call.llm_service.chatManager.chat.tool_format = mainChat.tool_format;\n                    this.agentTool.tool_call.llm_service.startLoop();\n                    let data = this.agentTool.tool_call.getDataDefault({ query, model: mainChat.model, version: mainChat.version });\n                    data = await this.agentTool.tool_call.callReAct(data);\n                    const res_json = utils.parseJsonContent(data.output_format);\n                    resolve(res_json[0]?.content || data.output_format);\n                }\n            });\n        });\n\n        listeners.close();\n        return {\n            content: result,\n            subagent_tool: true\n        };\n    }\n\n    public destroy(init: boolean = true): void {\n        if (this.windows && this.windows.length > 0) {\n            const windowsToClose = [...this.windows];\n\n            for (const name in this.agentTools) {\n                if (Object.prototype.hasOwnProperty.call(this.agentTools, name)) {\n                    const agentTool = this.agentTools[name];\n                    if (init) agentTool.tool_call.llm_service.chatManager.init();\n                    agentTool.tool_call.llm_service.stopLoop();\n                }\n            }\n\n            windowsToClose.forEach(win => {\n                if (win && !win.isDestroyed()) {\n                    win.close();\n                }\n            });\n\n            this.windows.length = 0;\n            this.windowListeners.clear();\n        }\n    }\n\n    public addAgentTool(\n        tool_name: string,\n        query_prompt: string,\n        agent_description: string,\n        agent_prompt: string,\n        tools: Record<string, any>,\n        options: SubAgentOptions = {},\n        mainSubAgent: boolean = false\n    ): void {\n        const { todolist = true, env = true, skill = true, mcp_server = false } = options;\n\n        const llm_service = new LLMService();\n        llm_service.chatManager.chat.id = null as any;\n        llm_service.chatManager.chat.name = tool_name;\n\n        const normalizedTools = this.normalizeTools(tools);\n\n        const tool_call = new ToolCall(\n            this.plugins, normalizedTools, llm_service, null,\n            { agent_prompt, subagent: true, todolist, env, skill, mcp_server, agent_name: tool_name },\n        );\n\n        this.agentTools[tool_name] = {\n            tool_call,\n            func: async ({ query }: { query: string }) => await this.query(query, tool_name),\n            getPrompt: () => ({\n                name: tool_name,\n                description: agent_description || \"\",\n                parameters: {\n                    type: \"object\",\n                    properties: {\n                        query: {\n                            type: \"string\",\n                            description: query_prompt || \"The task content that requires the assistant to complete.\"\n                        }\n                    },\n                    required: [\"query\"]\n                }\n            }),\n            mainSubAgent\n        };\n    }\n\n    public getMainSubAgent(): Record<string, AgentTool> {\n        return Object.fromEntries(\n            Object.entries(this.agentTools).filter(([, subagent]) => subagent.mainSubAgent)\n        );\n    }\n\n    private toolInit(): void {\n        if (!utils.getConfig()?.plugins?.cli_execute) return;\n\n        this.plugins = new Plugins();\n        this.plugins.loadInit(sysConfig.baseagent, true);\n        this.plugins.loadInit(sysConfig.transagent, true);\n\n        const agentDefs: Array<{\n            promptModule: string;\n            getTools: () => Record<string, any>;\n            options: SubAgentOptions;\n            isMain: boolean;\n        }> = [\n                {\n                    promptModule: 'url_summarizer',\n                    getTools: () => this.normalizeTools({\n                        web_crawler_toolkit: this.plugins.getTool(\"web_crawler_toolkit\"),\n                        browser_client: this.plugins.getTool(\"browser_client\"),\n                    }),\n                    options: { todolist: false, env: false, skill: false, mcp_server: false },\n                    isMain: false\n                },\n                {\n                    promptModule: 'web_searcher',\n                    getTools: () => this.normalizeTools({\n                        web_crawler_toolkit: this.plugins.getTool(\"web_crawler_toolkit\"),\n                        url_summarizer: this.agentTools[\"url_summarizer\"]\n                    }),\n                    options: { todolist: false, env: false, skill: false, mcp_server: false },\n                    isMain: false\n                },\n                {\n                    promptModule: 'error_solution_finder',\n                    getTools: () => this.normalizeTools({\n                        error_solution_search: this.plugins.getTool(\"error_solution_search\"),\n                        web_searcher: this.agentTools[\"web_searcher\"],\n                    }),\n                    options: { todolist: false, env: false, skill: false, mcp_server: false },\n                    isMain: false\n                },\n                {\n                    promptModule: 'chart_plotter',\n                    getTools: () => this.normalizeTools({\n                        cli_execute: this.plugins.getTool(\"cli_execute\"),\n                        read_tools_prompt: this.plugins.getTool(\"read_tools_prompt\"),\n                        list_dir: this.plugins.getTool(\"list_dir\"),\n                        write_to_file: this.plugins.getTool(\"write_to_file\"),\n                        replace_in_file: this.plugins.getTool(\"replace_in_file\"),\n                        image_vision: this.plugins.getTool(\"image_vision\"),\n                    }),\n                    options: { todolist: false, env: true, skill: false, mcp_server: false },\n                    isMain: true\n                },\n                {\n                    promptModule: 'tool_documentation_collector',\n                    getTools: () => this.normalizeTools({\n                        web_crawler_toolkit: this.plugins.getTool(\"web_crawler_toolkit\"),\n                        url_summarizer: this.agentTools[\"url_summarizer\"]\n                    }),\n                    options: { todolist: false, env: false, skill: false, mcp_server: false },\n                    isMain: false\n                },\n                {\n                    promptModule: 'tool_manager',\n                    getTools: () => this.normalizeTools({\n                        read_tools_prompt: this.plugins.getTool(\"read_tools_prompt\"),\n                        update_tool: this.plugins.getTool(\"update_tool\"),\n                        cli_execute: this.plugins.getTool(\"cli_execute\"),\n                        list_dir: this.plugins.getTool(\"list_dir\"),\n                        write_to_file: this.plugins.getTool(\"write_to_file\"),\n                        replace_in_file: this.plugins.getTool(\"replace_in_file\"),\n                        tool_documentation_collector: this.agentTools[\"tool_documentation_collector\"],\n                        error_solution_finder: this.agentTools[\"error_solution_finder\"],\n                    }),\n                    options: { todolist: false, env: true, skill: false, mcp_server: false },\n                    isMain: true\n                },\n                {\n                    promptModule: 'workflow_planner',\n                    getTools: () => this.normalizeTools({\n                        read_tools_prompt: this.plugins.getTool(\"read_tools_prompt\"),\n                    }),\n                    options: { todolist: true, env: true, skill: false, mcp_server: false },\n                    isMain: true\n                },\n                {\n                    promptModule: 'task_executor',\n                    getTools: () => this.normalizeTools({\n                        read_tools_prompt: this.plugins.getTool(\"read_tools_prompt\"),\n                        cli_execute: this.plugins.getTool(\"cli_execute\"),\n                        list_dir: this.plugins.getTool(\"list_dir\"),\n                        write_to_file: this.plugins.getTool(\"write_to_file\"),\n                        replace_in_file: this.plugins.getTool(\"replace_in_file\"),\n                        tool_manager: this.agentTools[\"tool_manager\"],\n                        chart_plotter: this.agentTools[\"chart_plotter\"],\n                        web_searcher: this.agentTools[\"web_searcher\"],\n                    }),\n                    options: { todolist: false, env: true, skill: false, mcp_server: false },\n                    isMain: true\n                },\n                {\n                    promptModule: 'deep_researcher',\n                    getTools: () => this.normalizeTools({\n                        literature_search: this.plugins.getTool(\"literature_search\"),\n                        web_crawler_toolkit: this.plugins.getTool(\"web_crawler_toolkit\"),\n                        browser_client: this.plugins.getTool(\"browser_client\"),\n                        url_summarizer: this.agentTools[\"url_summarizer\"],\n                    }),\n                    options: { todolist: false, env: true, skill: false, mcp_server: false },\n                    isMain: true\n                },\n            ];\n\n        for (const def of agentDefs) {\n            try {\n                const promptPath = path.join(__dirname, '..', '..', 'core', 'prompts', def.promptModule);\n                const prompt = require(promptPath).default;\n                this.addAgentTool(\n                    prompt.tool_name,\n                    prompt.query_prompt,\n                    prompt.agent_description,\n                    prompt.agent_prompt,\n                    def.getTools(),\n                    def.options,\n                    def.isMain\n                );\n            } catch (e: any) {\n                console.error(`[SubAgentWindow] Failed to register agent '${def.promptModule}':`, e.message);\n            }\n        }\n    }\n\n    public setup(): void {\n        // 预留：子 Agent 窗口的 IPC 事件绑定\n    }\n}"]}
